from collections import defaultdict

def detect_intrusion(packet_log: list[dict]) -> list[dict]:
    alerts = []
    fails = defaultdict(list)
    ports = defaultdict(set)

    for p in packet_log:
        src = p.get("src_ip")
        if p.get("status") == "failed" and p.get("dst_port") in (22, 3389, 445):
            fails[src].append(p)
        ports[src].add(p.get("dst_port"))

    for src, pkts in fails.items():
        if len(pkts) >= 5:
            alerts.append({"type": "brute_force", "src_ip": src, "count": len(pkts)})

    for src, seen in ports.items():
        if len(seen) > 15:
            alerts.append({"type": "port_scan", "src_ip": src, "ports": len(seen)})

    return alerts
